let _markdown = "\n\nIntroduction [#introduction]\n\n<FeedbackBlock id=\"6da7a5032d5bd733\" body=\"By default, all Markdown and MDX files need to be pre-compiled first. The same constraint also applies to the development server.\">\n  By default, all Markdown and MDX files need to be pre-compiled first. The same constraint also applies to the development server.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"edb19c1c0186b572\" body=\"This may result in longer dev server start times for large docs sites. You can enable Async or Dynamic mode on doc collections to improve this.\">\n  This may result in longer dev server start times for large docs sites. You can enable Async or Dynamic mode on doc collections to improve this.\n</FeedbackBlock>\n\nAsync Mode [#async-mode]\n\n<FeedbackBlock id=\"2c2903efb69f330c\" body=\"Async mode will generate collection outputs using async imports.\">\n  Async mode will generate collection outputs using async imports.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Docs Collection\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Docs Collection\">\n      Docs Collection\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Doc Collection\">\n      Doc Collection\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Docs Collection\">\n    ```ts\n    import { defineDocs } from 'fumadocs-mdx/config';\n\n    export const docs = defineDocs({\n      dir: 'content/docs',\n      docs: {\n        // [!code ++]\n        async: true,\n      },\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Doc Collection\">\n    ```ts\n    import { defineCollections } from 'fumadocs-mdx/config';\n\n    export const doc = defineCollections({\n      type: 'doc',\n      dir: 'content/docs',\n      // [!code ++]\n      async: true,\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"9d703cc1123c746b\" body=\"Depending on your bundler, this may reduce compilation time significantly on development server.\">\n  Depending on your bundler, this may reduce compilation time significantly on development server.\n</FeedbackBlock>\n\n<Callout title=\"For Next.js\">\n  Turbopack doesn't support lazy bundling at the moment, async mode will only improve server\n  performance.\n</Callout>\n\nDynamic Mode [#dynamic-mode]\n\n<FeedbackBlock id=\"e393c59f3c90bd71\" body=\"Dynamic mode works by performing on-demand compilation with MDX Remote.\">\n  Dynamic mode works by performing on-demand compilation with MDX Remote.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"ee4b97231c71ca18\" body=\"You need to install extra dependencies:\">\n  You need to install extra dependencies:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm i @fumadocs/mdx-remote shiki\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add @fumadocs/mdx-remote shiki\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add @fumadocs/mdx-remote shiki\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add @fumadocs/mdx-remote shiki\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<CodeBlockTabs defaultValue=\"Docs Collection\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Docs Collection\">\n      Docs Collection\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Doc Collection\">\n      Doc Collection\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Docs Collection\">\n    ```ts\n    import { defineDocs } from 'fumadocs-mdx/config';\n\n    export const docs = defineDocs({\n      dir: 'content/docs',\n      docs: {\n        // [!code ++]\n        dynamic: true,\n      },\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Doc Collection\">\n    ```ts\n    import { defineCollections } from 'fumadocs-mdx/config';\n\n    export const doc = defineCollections({\n      type: 'doc',\n      dir: 'content/docs',\n      // [!code ++]\n      dynamic: true,\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"f436ab5ba8a6858a\" body=\"Then, follow Dynamic Entry to access the collection from dynamic entry instead.\">\n  Then, follow [Dynamic Entry](/docs/mdx/entry/dynamic) to access the collection from dynamic entry instead.\n</FeedbackBlock>\n\n<Callout title=\"Constraints\" type=\"warn\">\n  Dynamic mode comes with some limitations on MDX features.\n\n  * **No import/export allowed in MDX files.** For MDX components, pass them from the `components` prop instead.\n  * **Images must be referenced with URL (e.g. `/images/test.png`).** Don't use **file paths** like `./image.png`. You should locate your images in the `public` folder and reference them with URLs.\n</Callout>\n\nUsage [#usage]\n\n<FeedbackBlock id=\"fe3dbd4fc30d1b50\" body=\"Frontmatter properties are still available on page object, but you need to invoke the load() async function to load the compiled content (and its exports).\">\n  Frontmatter properties are still available on `page` object, but you need to invoke the `load()` async function to load the compiled content (and its exports).\n</FeedbackBlock>\n\n<FeedbackBlock id=\"506c2c0c7f5b70af\" body=\"For example:\">\n  For example:\n</FeedbackBlock>\n\n```tsx title=\"page.tsx\"\nimport { source } from '@/lib/source';\nimport { getMDXComponents } from '@/mdx-components';\n\nconst page = source.getPage(['...']);\n\nif (page) {\n  // frontmatter properties are available\n  console.log(page.data);\n\n  // Markdown content requires await\n  const { body: MdxContent, toc } = await page.data.load();\n\n  console.log(toc);\n\n  return <MdxContent components={getMDXComponents()} />;\n}\n```\n\n<FeedbackBlock id=\"5b23ff1406d0f2d3\" body=\"When using Async or Dynamic mode, we highly recommend to use third-party services to implement search, which usually have better capability to handle massive amount of content to index.\">\n  When using Async or Dynamic mode, we highly recommend to use third-party services to implement search, which usually have better capability to handle massive amount of content to index.\n</FeedbackBlock>\n";
